  function G(){ return window.AutoCardUpdaterAPI||window.parent.AutoCardUpdaterAPI||window.top.AutoCardUpdaterAPI; }
  function S(v){ var n=parseInt(v,10); return isNaN(n)?0:n; }
  function Txt(v){ return (v==null||v==='')?'':String(v); }
  function W(){ var a=G(); if(a) return Promise.resolve(a); return new Promise(function(ok,fail){ var t=setInterval(function(){ var a=G(); if(a){clearInterval(t);ok(a);} },300); setTimeout(function(){clearInterval(t);fail(new Error('timeout'));},12000); }); }

  function load(){
    document.getElementById('st-debug').textContent='连接API...';
    W().then(function(a){
      document.getElementById('st-debug').textContent='查询数据...';
      var raw=null;
      if(typeof a.queryTableRows==='function'){ try { raw=a.queryTableRows({sheetKey:T.uid}); } catch(e){} }
      if(!raw && typeof a.exportTableAsJson==='function'){ try { var all=a.exportTableAsJson(); if(all&&all[T.uid]) raw=all[T.uid]; } catch(e){} }
      if(!raw){ document.getElementById('st-debug').textContent='无数据'; return; }
      var rows=Array.isArray(raw)?raw:(raw.rows||raw.data||raw.content||[]);
      if(!rows.length){ document.getElementById('st-debug').textContent='表空'; return; }
      var r=rows[0];
      if(!Array.isArray(r)) r=Object.values(r);
      document.getElementById('st-debug').textContent='已加载'+rows.length+'行';
      document.getElementById('st-name').textContent=Txt(r[1]);
      document.getElementById('st-corr').textContent=S(r[2]);
      document.getElementById('st-aff').textContent=S(r[3]);
      document.getElementById('st-m').textContent=S(r[5]);
      document.getElementById('st-c').textContent=S(r[6]);
      document.getElementById('st-v').textContent=S(r[7]);
      document.getElementById('st-a').textContent=S(r[8]);
      if(r[4]) document.getElementById('st-mental').textContent='心理：'+Txt(r[4]);
      document.getElementById('st-status').textContent=Txt(r[10]);
      if(typeof a.registerTableUpdateCallback==='function') a.registerTableUpdateCallback(function(){load();});
    }).catch(function(e){ document.getElementById('st-debug').textContent='失败:'+e.message; });
  }
  load();
}

var _nlw_retry = 0;
(function tryImport(){
  console.log('[沉香录] 第' + (++_nlw_retry) + '次尝试注入表格');
  var tpl = null;
  try { tpl = TEMPLATE; } catch(e) { console.log('[沉香录] TEMPLATE变量不存在'); }
  if (!tpl) { console.log('[沉香录] 等待TEMPLATE...'); setTimeout(tryImport, 500); return; }
  console.log('[沉香录] TEMPLATE已就绪，类型=' + typeof tpl);

  var api = null;
  try { api = window.AutoCardUpdaterAPI; } catch(e) {}
  if (!api) try { api = window.parent.AutoCardUpdaterAPI; } catch(e) {}
  if (!api) try { api = window.top.AutoCardUpdaterAPI; } catch(e) {}

  if (!api) {
    console.log('[沉香录] AutoCardUpdaterAPI不可用(window/parent/top均无)，1s后重试');
    setTimeout(tryImport, 1000);
    return;
  }
  console.log('[沉香录] API已获取，方法: ' + Object.keys(api).filter(function(k){ return typeof api[k]==='function'; }).join(', '));

  if (typeof api.importTemplateFromData !== 'function') {
    console.log('[沉香录] API缺少importTemplateFromData方法');
    return;
  }

  try {
    var existing = api.exportTableAsJson ? api.exportTableAsJson() : null;
    var sheetCount = existing ? Object.keys(existing).filter(function(k){return k.indexOf('sheet_')===0}).length : 0;
    if (sheetCount > 0) {
      console.log('[沉香录] 已有'+sheetCount+'张表，跳过注入');
    } else {
      api.importTemplateFromData(tpl, { merge: false });
      console.log('[沉香录] 表格模板注入成功');
    }
  } catch(e) {
    api.importTemplateFromData(tpl, { merge: false });
    console.log('[沉香录] 表格模板注入完成(existing check failed)');
  }
})();
</script>
<script>
const TEMPLATE_BASE64 = "";

function decodeBase64(base64Str) {
  try {
    const binaryStr = atob(base64Str);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      bytes[i] = binaryStr.charCodeAt(i);
    }
    const jsonStr = new TextDecoder('utf-8').decode(bytes);
    return JSON.parse(jsonStr);
  } catch (e) {
    console.error('Base64解码失败:', e);
    return null;
  }
}

const TEMPLATE = decodeBase64(TEMPLATE_BASE64);
console.log('表格模板已加载:', TEMPLATE);
</script>
